import pLimit, {limitFunction} from './index.js';
import {setTimeout as delay} from 'node:timers/promises';

const assert = (cond, msg) => { if (!cond) throw new Error('FAIL: ' + msg); console.log('ok:', msg); };

// 1. already idle resolves
{
  const limit = pLimit(1);
  await limit.onIdle();
  assert(true, 'already idle resolves');
}

// 2. multiple waiters, running + queue
{
  const limit = pLimit(2);
  const done = [];
  for (let i = 0; i < 5; i++) limit(async () => { await delay(20); done.push(i); });
  const results = await Promise.all([limit.onIdle(), limit.onIdle(), limit.onIdle()]);
  assert(results.length === 3, 'multiple waiters resolve');
  assert(done.length === 5 && limit.activeCount === 0 && limit.pendingCount === 0, 'all jobs done on idle');
}

// 3. rejected jobs
{
  const limit = pLimit(2);
  const p1 = limit(async () => { await delay(10); throw new Error('x'); });
  const p2 = limit(async () => { await delay(30); });
  p1.catch(() => {});
  await limit.onIdle();
  assert(limit.activeCount === 0, 'idle after rejected jobs');
  await p2;
}

// 4. clearQueue rejectOnClear:false releases waiters
{
  const limit = pLimit(1);
  // No active jobs, only queued (can't happen without active for concurrency 1 actually)
  // Use concurrency 2: two active, three queued
  const limit2 = pLimit(2);
  limit2(() => delay(1000));
  limit2(() => delay(1000));
  limit2(() => delay(1000));
  const waiter = limit2.onIdle();
  limit2.clearQueue();
  // still active 2, should not resolve yet
  let resolved = false;
  waiter.then(() => { resolved = true; });
  await delay(10);
  assert(!resolved, 'onIdle not resolved while active after clearQueue');
  // discard timers hold the event loop; just check pending 0
  assert(limit2.pendingCount === 0, 'clearQueue emptied queue');
}

// 5. clearQueue when queue empty and no jobs active, waiter pending
{
  const limit = pLimit(1);
  // create a waiter while a job is active, then clear (nothing queued)
  const job = limit(() => delay(10));
  const waiter = limit.onIdle();
  limit.clearQueue();
  await waiter;
  assert(limit.activeCount === 0, 'clearQueue releases waiter once no active and queue empty');
  await job;
}

// 6. enqueue on resolve one level deep
{
  const limit = pLimit(1);
  const log = [];
  const first = limit(async () => { log.push('first'); });
  first.then(() => { limit(async () => { log.push('second'); }); });
  await limit.onIdle();
  assert(log.join(',') === 'first,second', 'onIdle waits for job enqueued on resolve');
}

// 7. reserved slot counted / FIFO preserved
{
  const limit = pLimit(2);
  const order = [];
  const ps = [1,2,3,4].map(i => limit(async () => { order.push(i); await delay(5); }));
  // pending at start: 2
  assert(limit.pendingCount === 2, 'two pending reserved check');
  await limit.onIdle();
  assert(order.join(',') === '1,2,3,4', 'FIFO preserved');
}

// 8. limitFunction onIdle
{
  const lf = limitFunction(async x => { await delay(10); return x; }, {concurrency: 1});
  const p1 = lf(1), p2 = lf(2);
  await lf.onIdle();
  assert((await p1) === 1 && (await p2) === 2, 'limitFunction onIdle waits for all calls');
}

// 9. indefinite: onIdle doesn't resolve early after inner job completes fast
{
  const limit = pLimit(1);
  let ran = 0;
  limit(async () => { ran++; });
  limit(async () => { ran++; });
  await limit.onIdle();
  assert(ran === 2, 'onIdle waits for all queued');
}

console.log('ALL SCENARIOS PASSED');
EOF
