import {setTimeout as delay} from 'node:timers/promises';
import test from 'ava';
import pLimit, {limitFunction} from './index.js';

test('onIdle resolves immediately when already idle', async t => {
	const limit = pLimit(1);

	await t.notThrowsAsync(limit.onIdle());
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle waits for running and pending jobs', async t => {
	const limit = pLimit(2);
	const completed = [];

	limit(async () => {
		await delay(30);
		completed.push(1);
	});

	limit(async () => {
		await delay(10);
		completed.push(2);
	});

	limit(async () => {
		await delay(20);
		completed.push(3);
	});

	t.is(limit.pendingCount, 1);

	await limit.onIdle();

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
	t.deepEqual(completed, [2, 3, 1]);
});

test('onIdle resolves after jobs that reject', async t => {
	const limit = pLimit(2);
	const error = new Error('💥');

	const rejecting = limit(async () => {
		await delay(10);
		throw error;
	});
	rejecting.catch(() => {});

	limit(async () => {
		await delay(30);
	});

	await limit.onIdle();

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle supports multiple waiters', async t => {
	const limit = pLimit(1);
	let completed = 0;

	limit(async () => {
		await delay(20);
		completed++;
	});
	limit(async () => {
		await delay(20);
		completed++;
	});

	const results = await Promise.all([
		limit.onIdle(),
		limit.onIdle(),
		limit.onIdle(),
	]);

	t.deepEqual(results, [undefined, undefined, undefined]);
	t.is(completed, 2);
	t.is(limit.activeCount, 0);
});

test('onIdle does not report idle when a resolving job enqueues another job', async t => {
	const limit = pLimit(1);
	const log = [];

	const first = limit(async () => {
		log.push('first');
		return 'first';
	});

	first.then(() => {
		limit(async () => {
			await delay(10);
			log.push('second');
		});
	});

	await limit.onIdle();

	t.deepEqual(log, ['first', 'second']);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('clearQueue resolves onIdle waiters when the queue empties with no active jobs', async t => {
	const limit = pLimit(1);

	// No jobs are running, only a waiter registered for a queue that is about to
	// be discarded. Under `rejectOnClear: false` the discarded promises stay
	// unresolved, but `onIdle` must still be released.
	limit(() => delay(0)).catch(() => {});
	await delay(0);

	const queued = limit(() => delay(1000));
	queued.catch(() => {});

	const idlePromise = limit.onIdle();
	limit.clearQueue();

	await t.notThrowsAsync(idlePromise);
	t.is(limit.pendingCount, 0);
});

test('clearQueue does not resolve onIdle waiters while jobs are still active', async t => {
	const limit = pLimit(2);

	const running = [
		limit(async () => delay(50)),
		limit(async () => delay(50)),
	];
	limit(async () => delay(50));
	limit(async () => delay(50));

	let resolved = false;
	const idlePromise = limit.onIdle().then(() => {
		resolved = true;
	});

	limit.clearQueue();
	t.is(limit.pendingCount, 0);

	await delay(10);
	t.false(resolved);

	await Promise.all(running);
	await idlePromise;
	t.true(resolved);
	t.is(limit.activeCount, 0);
});

test('onIdle preserves FIFO ordering and concurrency', async t => {
	const limit = pLimit(2);
	const order = [];

	const promises = [1, 2, 3, 4, 5].map(index => limit(async () => {
		order.push(index);
		await delay(5);
		return index;
	}));

	t.is(limit.pendingCount, 3);

	const results = await limit.onIdle().then(() => Promise.all(promises));

	t.deepEqual(order, [1, 2, 3, 4, 5]);
	t.deepEqual(results, [1, 2, 3, 4, 5]);
});

test('onIdle resolves after a concurrency increase drains the queue', async t => {
	const limit = pLimit(1);
	const completed = [];

	for (const index of [1, 2, 3]) {
		limit(async () => {
			await delay(10);
			completed.push(index);
		});
	}

	limit.concurrency = 3;

	await limit.onIdle();

	t.deepEqual(completed, [1, 2, 3]);
	t.is(limit.activeCount, 0);
});

test('limitFunction exposes onIdle', async t => {
	const limitedFunction = limitFunction(async value => {
		await delay(10);
		return value;
	}, {concurrency: 1});

	const first = limitedFunction(1);
	const second = limitedFunction(2);

	const values = await limitedFunction.onIdle().then(() => Promise.all([first, second]));

	t.deepEqual(values, [1, 2]);
});

