import Queue from 'yocto-queue';

export default function pLimit(concurrency) {
	let rejectOnClear = false;

	if (typeof concurrency === 'object') {
		({concurrency, rejectOnClear = false} = concurrency);
	}

	validateConcurrency(concurrency);

	if (typeof rejectOnClear !== 'boolean') {
		throw new TypeError('Expected `rejectOnClear` to be a boolean');
	}

	const queue = new Queue();
	let activeCount = 0;

	const idleWaiters = new Set();
	let idleCheckScheduled = false;
	// Incremented whenever the active or queued work changes. Used to detect
	// work that is enqueued and drained while an idle check is in flight.
	let activityVersion = 0;

	const isEmpty = () => activeCount === 0 && queue.size === 0;

	const resolveIdleWaiters = () => {
		for (const resolve of idleWaiters) {
			resolve();
		}

		idleWaiters.clear();
	};

	const scheduleIdleCheck = () => {
		if (idleCheckScheduled || idleWaiters.size === 0) {
			return;
		}

		idleCheckScheduled = true;
		queueMicrotask(() => {
			idleCheckScheduled = false;

			if (!isEmpty()) {
				return;
			}

			// A job that resolves may enqueue another job from a promise
			// continuation. Confirm the limiter stays idle for a microtask before
			// reporting it as idle, and re-check the activity version to catch work
			// that started and finished in the meantime.
			const version = activityVersion;
			queueMicrotask(() => {
				if (isEmpty() && activityVersion === version) {
					resolveIdleWaiters();
					return;
				}

				scheduleIdleCheck();
			});
		});
	};

	const resumeNext = () => {
		// Process the next queued function if we're under the concurrency limit
		if (activeCount < concurrency && queue.size > 0) {
			activeCount++;
			activityVersion++;
			queue.dequeue().run();
		}
	};

	const next = () => {
		activeCount--;
		activityVersion++;
		resumeNext();
		scheduleIdleCheck();
	};

	const run = async (function_, resolve, arguments_) => {
		// Execute the function and capture the result promise
		const result = (async () => function_(...arguments_))();

		// Resolve immediately with the promise (don't wait for completion)
		resolve(result);

		// Wait for the function to complete (success or failure)
		// We catch errors here to prevent unhandled rejections,
		// but the original promise rejection is preserved for the caller
		try {
			await result;
		} catch {}

		// Decrement active count and process next queued function
		next();
	};

	const enqueue = (function_, resolve, reject, arguments_) => {
		const queueItem = {reject};

		// Queue the internal resolve function instead of the run function
		// to preserve the asynchronous execution context.
		new Promise(internalResolve => { // eslint-disable-line promise/param-names
			queueItem.run = internalResolve;
			queue.enqueue(queueItem);
			activityVersion++;
		}).then(run.bind(undefined, function_, resolve, arguments_)); // eslint-disable-line promise/prefer-await-to-then

		// Start processing immediately if we haven't reached the concurrency limit
		if (activeCount < concurrency) {
			resumeNext();
		}
	};

	const generator = (function_, ...arguments_) => new Promise((resolve, reject) => {
		enqueue(function_, resolve, reject, arguments_);
	});

	Object.defineProperties(generator, {
		activeCount: {
			get: () => activeCount,
		},
		pendingCount: {
			get: () => queue.size,
		},
		clearQueue: {
			value() {
				if (!rejectOnClear) {
					queue.clear();
					activityVersion++;
					scheduleIdleCheck();
					return;
				}

				const abortError = AbortSignal.abort().reason;

				while (queue.size > 0) {
					queue.dequeue().reject(abortError);
				}

				activityVersion++;
				scheduleIdleCheck();
			},
		},
		concurrency: {
			get: () => concurrency,

			set(newConcurrency) {
				validateConcurrency(newConcurrency);
				concurrency = newConcurrency;

				queueMicrotask(() => {
					// eslint-disable-next-line no-unmodified-loop-condition
					while (activeCount < concurrency && queue.size > 0) {
						resumeNext();
					}
				});
			},
		},
		onIdle: {
			value() {
				return new Promise(resolve => {
					if (isEmpty()) {
						resolve();
						return;
					}

					idleWaiters.add(resolve);
					scheduleIdleCheck();
				});
			},
		},

		map: {
			async value(iterable, function_) {
				const promises = [];

				try {
					Array.from(iterable, (value, index) => {
						const promise = generator(function_, value, index);
						promises.push(promise);
						return promise;
					});
				} catch (error) {
					// The iterable threw, so `Promise.all` never observes the already scheduled promises. Observe them here to avoid unhandled rejections.
					for (const promise of promises) {
						promise.catch(() => {}); // eslint-disable-line promise/prefer-await-to-then
					}

					throw error;
				}

				return Promise.all(promises);
			},
		},
	});

	return generator;
}

